/*global chrome*/
import utils from './utils';

const a = document.body;
const b = {childList: true, subtree: true};

let enabledAutoS
let interval

const startScroll =() => {
  if (enabledAutoS) {
    return false
  }

  enabledAutoS = true

  interval = setInterval(function () {
    window.scrollBy(0, 8)
  }, 80);
}

const stopScroll = () => {
  if (enabledAutoS) {
    enabledAutoS = false
    clearInterval(interval)
  }
};

const handleItemsAds = (e) => {
  try {
    chrome.storage.local.get(['onlyAds', 'adsList'], function(item) {
      const adsList = item.adsList || {};
      const h3 = document.querySelector('.x1hc1fzr.x1unhpq9 h3');
      // const leftNodeSpam = document.querySelector('#has-finished-comet-page');
      const posts = document.querySelectorAll('.x1hc1fzr.x1unhpq9.x6o7n8i .x1lliihq .x1n2onr6.x1ja2u2z > .html-div.xdj266r.x14z9mp.xat24cr.x1lziwak.xexx8yu.xyri2b.x18d9i69.x1c1uobl')

      const containerFeed = h3?.parentNode?.children;

      if (!containerFeed || !containerFeed.length) {
        return;
      }

      const nodes = containerFeed[containerFeed.length -1];
      // console.log({
      //   posts,
      //   containerFeed,
      //   nodes,
      // })
      if (!nodes) {
        return;
      }

      if (!nodes.classList.contains("adsContainer")) {
        nodes.classList.add('adsContainer');
        nodes.insertAdjacentHTML('beforeend', '<p class="notification">If you see this message, it means that Facebook is loading new posts and hiding them from the feed, except for advertising posts and announcements.</p>');
      }

      Array.from(posts)?.filter(e => !e.classList.contains("hide") && !e.classList.contains("viewAds"))?.map(e => {
        const singleAds = e.querySelector('a .x1vjfegm a');
        const multipleAds = e.querySelector('li .x1vjfegm a');

        if (singleAds?.getAttribute('target') || multipleAds?.getAttribute('target')) {
          e.classList.add('viewAds');
          const title = e.querySelector('h4');

          const ad = Object.values(adsList).find(e => e.pageName === title?.innerText);

          if (!ad) {
            return;
          }
          const ref = `https://www.facebook.com/ads/library/?active_status=all&ad_type=all&country=ALL&view_all_page_id=${ad.pageId}&search_type=page&media_type=all`
          title.parentNode?.parentNode?.parentNode?.parentNode?.parentNode?.parentNode?.insertAdjacentHTML('beforeend', `<a target="_blank" href="${ref}" class="adLibraryLink">Ad Library</a>`);
        } else {
          if (!item?.onlyAds || e.classList.contains("notification")) {
            return;
          }
          e.classList.add('hide');

        }
      })

    });
  } catch (e) {
    console.log(e)
  }
}


const start = () => {
  try {
    const observerItemsAds = new MutationObserver(handleItemsAds);

    observerItemsAds.observe(a, b);

    chrome.storage.local.get(['autoScroll'], function(item) {
      if (!item?.autoScroll) {
        return;
      }
      startScroll();
    })
  } catch (e) {

  }
};

chrome.storage.onChanged.addListener((changes, namespace) => {
  try {
    if (changes.onlyAds) {
      if (changes.onlyAds.newValue) {
        handleItemsAds();
        return;
      }
      const elements = Array.from(document.querySelectorAll('.hide'));

      elements.map(node => node.classList.remove("hide"))
      return;
    }

    if (changes.autoScroll) {
      if (changes.autoScroll.newValue) {
        startScroll();
        return;
      }
      stopScroll();
    }
  } catch (e) {

  }
});

window.addEventListener("message", async function (event) {
  try {
    if (event?.data?.type && (event?.data?.type === "ADS" || event?.data?.type === 'ADS SPONSORED')) {
      const payload = event?.data?.payload || {};

      const ad = utils.getParsedAd(payload);

      if (!ad) {
        return;
      }

      utils.saveAd(ad);

      const nodes = document.querySelectorAll('h4 span a strong span');
      const title = ad.pageName;
      // console.log(Array.from(nodes).map(el => el.innerText) + ' ==== ' + title);
      Array.from(nodes).map(el => {

        if (el?.innerText === title) {
          const ref = `https://www.facebook.com/ads/library/?active_status=all&ad_type=all&country=ALL&view_all_page_id=${ad.pageId}&search_type=page&media_type=all`
          el.parentNode?.parentNode?.parentNode?.parentNode?.parentNode?.parentNode?.parentNode?.insertAdjacentHTML('beforeend', `<a target="_blank" href="${ref}" class="adLibraryLink">Ad Library</a>`);
        }
      });

      // setTimeout(() => {
      //   const nodes = document.querySelectorAll('h4 span a strong span');
      //   const title = ad.pageName;
      //   // console.log(Array.from(nodes).map(el => el.innerText) + ' ==== ' + title);
      //   Array.from(nodes).map(el => {
      //
      //     if (el?.innerText === title) {
      //       const ref = `https://www.facebook.com/ads/library/?active_status=all&ad_type=all&country=ALL&view_all_page_id=${ad.pageId}&search_type=page&media_type=all`
      //       el.parentNode?.parentNode?.parentNode?.parentNode?.insertAdjacentHTML('beforeend', `<a target="_blank" href="${ref}" class="adLibraryLink">Ad Library</a>`);
      //     }
      //   });
      // }, 2000);
    }
  } catch (e) {
    // console.log(e);
    // if (event?.data?.type && (event?.data?.type === "ADS" || event?.data?.type === 'ADS SPONSORED')) {
    //   console.log(event?.data?.payload)
    // }
  }

})

start();

export {}