    let btnText = payload.node.comet_sections?.context_layout?.story?.comet_sections?.actor_photo?.story?.attachments && payload.node.comet_sections?.context_layout?.story?.comet_sections?.actor_photo?.story?.attachments[0]?.action_links ? payload.node.comet_sections?.context_layout?.story?.comet_sections?.actor_photo?.story?.attachments[0]?.action_links[0]?.link_type : 'Show more';
    let subAttachment = attachments?.styles?.attachment?.subattachments && attachments?.styles?.attachment?.subattachments[0];
    let destLink = subAttachment?.call_to_action_renderer?.action_link?.url || attachments.comet_footer_renderer.attachment?.call_to_action_renderer?.action_link?.url || attachments.comet_footer_renderer.attachment?.ghl_mocked_footer_info?.link || attachments.comet_footer_renderer.attachment?.story_attachment_link_renderer?.attachment?.url


    let pageLink = 'https://facebook.com/' + pageId

    // let comet_ufi_summary_and_actions_renderer = object.node.comet_sections.feedback.story.comet_feed_ufi_container.story.feedback_context.feedback_target_with_context.ufi_renderer.feedback.comet_ufi_summary_and_actions_renderer
    // let feedbackReactions = comet_ufi_summary_and_actions_renderer.feedback

    let comet_ufi_summary_and_actions_renderer = payload?.node?.comet_sections?.feedback?.story?.comet_feed_ufi_container?.story?.story_ufi_container?.story?.feedback_context?.feedback_target_with_context?.comet_ufi_summary_and_actions_renderer || payload.node.comet_sections.feedback?.story?.comet_feed_ufi_container?.story?.feedback_context?.feedback_target_with_context.ufi_renderer.feedback.comet_ufi_summary_and_actions_renderer
