const saveAd = (adData) => {
  chrome.storage.local.get(['adsList'], function(item) {
    const adsList = item.adsList || new Set()

    if (adData.haveVideo) {
      adData.postLink = adData.postLink.replace('posts', 'videos');
    }

    let ad = {
      postId: Number(adData.postLink.match(/([^\/\D/g/]*)\/*$/).pop()),
      postLink: adData.postLink,
      banner: adData.banner,
      bannerW: adData.bannerW,
      bannerH: adData.bannerH,
      videoLink: adData.videoLink,
      haveVideo: adData.haveVideo,
      profilePicture: adData.profilePicture,
      pageId: adData.pageId,
      id: adData.pageId,
      pageName: adData.pageName,
      postText: adData.postText,
      headline: adData.headline,
      smalltext: adData.smalltext,
      buttonText: adData.buttonText,
      destLink: adData.destLink,
      likes: adData.likes,
      videoUrl: adData.videoUrl,
      savedAt: Date.now(),
      pageLink: adData.pageLink,
      btnText: adData.btnText,
      subattachments: adData.subattachments,
      adData: adData?.adData
    }
    adsList[ad.postId] = ad;

    chrome.storage.local.set({'adsList': adsList}, function() {});

  });
}

export default {
  getParsedAd,
  saveAd
}